class ProfileScreen extends StatelessWidget{final String name;const ProfileScreen({super.key,required this.name});Future<void> openInstagram()async{await launchUrl(Uri.parse('https://instagram.com/'),mode:LaunchMode.externalApplication);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[const CircleAvatar(radius:38,child:Icon(Icons.person,size:38)),const SizedBox(height:10),Text(name,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w700)),const SizedBox(height:12),FilledButton.icon(onPressed:openInstagram,icon:const Icon(Icons.open_in_new),label:const Text('Instagram')),const SizedBox(height:24),const Expanded(child:GridPlaceholder())])));}
class MyProfile extends StatelessWidget{const MyProfile({super.key});@override Widget build(BuildContext context)=>const Padding(padding:EdgeInsets.all(20),child:Column(children:[CircleAvatar(radius:38,child:Icon(Icons.person,size:38)),SizedBox(height:10),Text('you',style:TextStyle(fontSize:22,fontWeight:FontWeight.w700)),SizedBox(height:24),Expanded(child:GridPlaceholder())]));}
